class GymMember{protected String memberId;protected int monthlyFee;private int sessions;GymMember(String id,int fee){if(id==null||id.trim().length()<4||fee<=0)throw new IllegalArgumentException();memberId=id;monthlyFee=fee;}void attendSession(){sessions++;}int getSessionsAttended(){return sessions;}String displayInfo(){return "Standard Member | Sessions: "+sessions;}}
class PremiumMember extends GymMember{String trainerName;PremiumMember(String i,int f,String t){super(i,f);trainerName=t;}String displayInfo(){return "Premium Member | Trainer: "+trainerName+" | Sessions: "+getSessionsAttended();}}
class EliteMember extends PremiumMember{String lockerNumber;EliteMember(String i,int f,String t,String l){super(i,f,t);lockerNumber=l;}String displayInfo(){return "Elite Member | Trainer: "+trainerName+" | Locker: "+lockerNumber+" | Sessions: "+getSessionsAttended();}}
class GroupClassMember extends GymMember{String className;GroupClassMember(String i,int f,String c){super(i,f);className=c;}String displayInfo(){return "Group Class Member | Class: "+className+" | Sessions: "+getSessionsAttended();}}
public class Main{static String classifyGeneration(GymMember m){if(m instanceof EliteMember)return "Multilevel descendant (3 generations deep)";if(m instanceof GroupClassMember)return "Hierarchical sibling (independent branch)";return "Other";}static int getTotalSessionsAttended(GymMember[] ms){int s=0;for(GymMember m:ms)s+=m.getSessionsAttended();return s;}public static void main(String[]a){}}